return {["fb21_01"]={["down"]=[[fb21_04]],["dsc"]=[[你的面前是一座林木繁茂的高山，几座山峰在云雾中隐约可见，一条石阶向山上延伸，走着几个进香客。]],["fightBackground"]=[[山外]],["id"]=[[fb21_01]],["name"]=[[武当玄岳门]],["permission"]=1,["right"]=[[fb21_02]],["role1"]=[[fb21r01_1]],["role2"]=[[fb21r01_2]],["stepMusic"]=[[jiaobu]]},["fb21_02"]={["down"]=[[fb21_44]],["dsc"]=[[是武林中极负盛名的武当解剑岩，岩下解剑池水明澈照人。武林人士经此都自觉解剑，以示对武当派的尊敬。千百年来，概无例外。]],["fightBackground"]=[[山外]],["id"]=[[fb21_02]],["left"]=[[fb21_01]],["name"]=[[解剑岩]],["permission"]=1,["right"]=[[fb21_03]],["role1"]=[[fb21r02_1]],["role2"]=[[fb21r02_2]],["stepMusic"]=[[jiaobu]]},["fb21_03"]={["dsc"]=[[这是松林深处，暗无天日，朦胧中只感觉到左右前后到处都是树影。地上有一两个死人骷髅，发着绿荧荧的磷光。你惊骇之间，一脚踩在钢针般的松针上！]],["fightBackground"]=[[森林外]],["id"]=[[fb21_03]],["left"]=[[fb21_02]],["name"]=[[武当松林]],["permission"]=1,["role1"]=[[ybritem1]],["role2"]=[[dhpd]],["stepMusic"]=[[jiaobu]]},["fb21_04"]={["down"]=[[fb21_05]],["dsc"]=[[这里是进入武当山的第一道宫宇遇真宫，宽敞无比，可容千人食宿，是进香客的一大歇脚处。三丰真人曾在此结庵修炼，因此宫中供着张三丰真人像。]],["id"]=[[fb21_04]],["item1"]=[[fb21item13]],["name"]=[[遇真宫]],["permission"]=1,["role1"]=[[fb21r04_1]],["role2"]=[[fb21r04_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb21_01]]},["fb21_05"]={["down"]=[[fb21_06]],["dsc"]=[[你穿行在一片茂密的柏林中，阴森郁翠，怪石嶙峋，草深没人。不时地有兔子从你的身边飞跑而过。]],["fightBackground"]=[[森林外]],["id"]=[[fb21_05]],["item1"]=[[fb21item105]],["name"]=[[柏林]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb21_04]]},["fb21_06"]={["down"]=[[fb21_07]],["dsc"]=[[此处连绵十几里山势陡峭，名为好汉坡，山路两旁种满了细竹，翠色横空景象怡人，不知不觉让你忘记了爬坡的疲劳。]],["fightBackground"]=[[山外]],["id"]=[[fb21_06]],["name"]=[[好汉坡]],["permission"]=1,["role1"]=[[fb21r06_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb21_05]]},["fb21_07"]={["down"]=[[fb21_09]],["dsc"]=[[你走在登山的路径上，路的左右各有一条大铁链，像两条长蛇向山上山下蜿蜒爬去。满眼是乔木夹道，如行于绿幕中。]],["fightBackground"]=[[山外]],["id"]=[[fb21_07]],["name"]=[[山路]],["permission"]=1,["right"]=[[fb21_08]],["role1"]=[[fb21r07_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb21_06]]},["fb21_08"]={["dsc"]=[[相传当年真武进山修炼，日久思归，偶遇一老妇持铁杵研磨。问磨杵为何？答以磨针。又问铁杵岂能磨针？答云功到自然成。真武由此醒悟，终于修炼成仙。后人因建磨针井道观以为纪念。]],["fightBackground"]=[[山外]],["id"]=[[fb21_08]],["left"]=[[fb21_07]],["name"]=[[磨针井]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb21_09"]={["down"]=[[fb21_11]],["dsc"]=[[此处地处坡陀之隘，形势险要，相传净乐国太子(少年真武)入山修道时，曾在此留住读书，故名叫太子坡，远处峰回路转，忽明忽灭，尽在云雾之中。]],["fightBackground"]=[[山外]],["id"]=[[fb21_09]],["name"]=[[太子坡]],["permission"]=1,["right"]=[[fb21_10]],["stepMusic"]=[[jiaobu]],["up"]=[[fb21_07]]},["fb21_10"]={["dsc"]=[[复真观五层楼构造奇特，其间有十二根梁枋交叉重叠，下面仅用一柱支撑，即有名的“一柱十二梁”。在这里俯瞰群山，烟云迷离，远望金顶，一柱擎天，为观景胜地。]],["fightBackground"]=[[山外]],["id"]=[[fb21_10]],["left"]=[[fb21_09]],["name"]=[[复真观五层口]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb21_11"]={["down"]=[[fb21_13]],["dsc"]=[[你走入山坞中，有一道石梁跨溪而建，这里是九渡涧的下流，各岭之水均在此交汇，景色极佳。再往上就是陡峭的十八盘了。]],["fightBackground"]=[[山外]],["id"]=[[fb21_11]],["name"]=[[石梁]],["permission"]=1,["right"]=[[fb21_12]],["role1"]=[[2019qxcdg1a]],["role2"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]],["up"]=[[fb21_09]]},["fb21_12"]={["dsc"]=[[这里是石梁边的一间小吃店，卖些简单的饮食，专门赚那些游客的钱。]],["id"]=[[fb21_12]],["left"]=[[fb21_11]],["name"]=[[小吃店]],["permission"]=2,["role1"]=[[fb21r12_1]],["role2"]=[[fb21r12_2]],["stepMusic"]=[[jiaobu]]},["fb21_13"]={["down"]=[[fb21_14]],["dsc"]=[[这是一个很大的斜坡，俗称十八盘，大石阶一级一级笔直而上，颇费脚力。这里坡坡有神，拐拐有祠，往上十里之后即是凌霄宫。]],["id"]=[[fb21_13]],["name"]=[[十八盘]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb21_11]]},["fb21_14"]={["down"]=[[fb21_15]],["dsc"]=[[你已走到了展旗峰下，前面就是武当山最为宏大的宫宇紫霄宫了。殿宇依山而筑，高低错落有致。周围古木森森，翠竹成林，景色清幽。这里是武当的主要活动场所。]],["id"]=[[fb21_14]],["name"]=[[紫霄宫门]],["permission"]=1,["role1"]=[[fb21r14_1]],["role2"]=[[fb21r14_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb21_13]]},["fb21_15"]={["down"]=[[fb21_20]],["dsc"]=[[这是一个由大石板铺成的广场，是武当弟子学习武功和互相切磋的地点。周围种满了梧桐树，一到秋天就是满地的落叶。一个道童正在打扫。南边是凌霄宫三清殿。]],["fightBackground"]=[[擂台]],["id"]=[[fb21_15]],["name"]=[[广场]],["permission"]=1,["right"]=[[fb21_16]],["role1"]=[[fb21r15_1]],["role2"]=[[fb21r15_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb21_14]]},["fb21_16"]={["down"]=[[fb21_21]],["dsc"]=[[你走在登山的路径上，路的左右各有一条大铁链，像两条长蛇向山上山下蜿蜒爬去。满眼是乔木夹道，如行于绿幕中。]],["fightBackground"]=[[山外]],["id"]=[[fb21_16]],["item1"]=[[fb21item11]],["left"]=[[fb21_15]],["name"]=[[山路]],["permission"]=1,["right"]=[[fb21_17]],["stepMusic"]=[[jiaobu]]},["fb21_17"]={["dsc"]=[[你走在登山的路径上，路的左右各有一条大铁链，像两条长蛇向山上山下蜿蜒爬去。满眼是乔木夹道，如行于绿幕中。]],["fightBackground"]=[[山外]],["id"]=[[fb21_17]],["left"]=[[fb21_16]],["name"]=[[山路]],["permission"]=2,["right"]=[[fb21_18]],["stepMusic"]=[[jiaobu]]},["fb21_18"]={["dsc"]=[[眼前豁然开朗，你轻松地走在桃园边的小路上。两边是桃树林，树上盛开着粉红的桃花，红云一片，望不到边。南北方向是通向两个桃园的入口。]],["fightBackground"]=[[山外]],["id"]=[[fb21_18]],["left"]=[[fb21_17]],["name"]=[[小路]],["permission"]=2,["right"]=[[fb21_19]],["role1"]=[[fb21r18_1]],["stepMusic"]=[[jiaobu]]},["fb21_19"]={["dsc"]=[[这里的景色实在是太美了，到处都是野花野草，阵阵花香飘来。你不禁想倒在地上睡一小会儿……]],["id"]=[[fb21_19]],["left"]=[[fb21_18]],["name"]=[[桃园]],["permission"]=2,["role1"]=[[fb21r19_2]],["role2"]=[[fb21r19_100]],["role3"]=[[fb21r19_101]],["stepMusic"]=[[jiaobu]]},["fb21_20"]={["dsc"]=[[这里是凌霄宫的三清殿，是武当派会客的地点。供着元始天尊、太上道君和太上老君的神像，香案上香烟缭绕。东西两侧是走廊，北边是练武的广场。]],["id"]=[[fb21_20]],["item1"]=[[fb21item12]],["name"]=[[三清殿]],["permission"]=1,["role1"]=[[fb21r20_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb21_15]]},["fb21_21"]={["down"]=[[fb21_24]],["dsc"]=[[这里是群山环抱中的太子岩，岩上有一块三清石和一座太子亭。]],["fightBackground"]=[[山外]],["id"]=[[fb21_21]],["item1"]=[[fb21item9]],["name"]=[[太子岩]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb21_16]]},["fb21_22"]={["dsc"]=[[这是一处险峻的悬崖峭壁，相传真武帝在此舍身得道。崖上立有铁栅栏，防止有人自杀步真武帝的后尘。]],["fightBackground"]=[[山外]],["id"]=[[fb21_22]],["name"]=[[舍身崖]],["permission"]=2,["right"]=[[fb21_23]],["role1"]=[[fb21r22_1]],["role2"]=[[fb21r22_100]],["stepMusic"]=[[jiaobu]]},["fb21_23"]={["down"]=[[fb21_25]],["dsc"]=[[这里是武当三十六岩之最，松树翳天，木石争奇，峭壁万仞。在悬崖之半筑有一宫宇，下临深渊，工程浩大。宫前有一石柱，自峭壁上横出。]],["fightBackground"]=[[山外]],["id"]=[[fb21_23]],["item1"]=[[fb21item6]],["item2"]=[[fb21item6]],["left"]=[[fb21_22]],["name"]=[[南岩峰]],["permission"]=2,["right"]=[[fb21_24]],["role1"]=[[fb21r23_2]],["stepMusic"]=[[jiaobu]]},["fb21_24"]={["down"]=[[fb21_26]],["dsc"]=[[眼前豁然开朗，你轻松地走在榔梅园的小路上。两边是桃树林，树上盛开着粉红的桃花，红云一片，望不到边。远处是高高的天柱峰。]],["id"]=[[fb21_24]],["item1"]=[[fb21item10]],["left"]=[[fb21_23]],["name"]=[[榔梅园]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb21_21]]},["fb21_25"]={["down"]=[[fb21_27]],["dsc"]=[[这是南岩宫前的一根石柱，雕成龙形，自峭壁上横出，犹如飞龙在天。石柱仅粗如屋梁，旁无扶栏，前有白云缭绕，下有万丈深渊，稍一失足，即尸骨无存。]],["id"]=[[fb21_25]],["item1"]=[[fb21item5]],["item2"]=[[fb21item6]],["item3"]=[[fb21item6]],["item4"]=[[fb21item6]],["name"]=[[石柱]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb21_23]]},["fb21_26"]={["down"]=[[fb21_28]],["dsc"]=[[这是一狭长的脊岭，两侧悬削，一无所傍，但见白云朵朵，冉冉而过，山风拂拂，阵阵袭来。数百只乌鸦正翱翔云际，黑白分明，蔚成奇观。]],["id"]=[[fb21_26]],["name"]=[[乌鸦岭]],["permission"]=2,["role1"]=[[fb21r26_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb21_24]]},["fb21_27"]={["down"]=[[fb21_29]],["dsc"]=[[这里是就是南岩宫。此宫半卧悬崖之下。殿内三清坐像金光闪闪，气宇轩昂。殿内天井处芳草迷径，百卉争妍。南面高台就是玉螣七化阵。叛师或半路投师者珍重。]],["id"]=[[fb21_27]],["name"]=[[南岩宫]],["permission"]=2,["role1"]=[[fb21r27_1]],["role2"]=[[fb21r27_2]],["role3"]=[[fb21r27_3]],["role4"]=[[fb21r27_100]],["stepMusic"]=[[jiaobu]],["up"]=[[fb21_25]]},["fb21_28"]={["down"]=[[fb21_30]],["dsc"]=[[只见三座奇峰突兀，惊险无比，行人多不敢放胆在此玩赏风景。]],["fightBackground"]=[[山外]],["id"]=[[fb21_28]],["name"]=[[三老峰]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb21_26]]},["fb21_29"]={["dsc"]=[[这里是就是南岩宫高台。高台孤悬崖侧，四望临渊，深不可测。山风夹耳，松清涤面，顿觉心窍大开。武当玉螣七化阵就在这里。]],["fightBackground"]=[[山外]],["id"]=[[fb21_29]],["item1"]=[[fb21r29_5]],["item2"]=[[fb21r29_6]],["item3"]=[[fb21r29_7]],["item4"]=[[fb21item15]],["name"]=[[高台]],["permission"]=2,["role1"]=[[fb21r29_1]],["role2"]=[[fb21r29_2]],["role3"]=[[fb21r29_3]],["role4"]=[[fb21r29_4]],["stepMusic"]=[[jiaobu]],["up"]=[[fb21_27]]},["fb21_30"]={["down"]=[[fb21_31]],["dsc"]=[[只见五座奇峰突兀，惊险无比，行人多不敢放胆在此玩赏风景。]],["fightBackground"]=[[山外]],["id"]=[[fb21_30]],["item1"]=[[ycitem1]],["name"]=[[五老峰]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb21_28]]},["fb21_31"]={["down"]=[[fb21_32]],["dsc"]=[[一块巨大的岩石看上去好像一个虎头正张大了血盆大口咆哮，虎身隐藏在草木丛中。]],["fightBackground"]=[[山外]],["id"]=[[fb21_31]],["name"]=[[虎头岩]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb21_30]]},["fb21_32"]={["down"]=[[fb21_33]],["dsc"]=[[这里已近武当绝顶，只见石梯直耸，危磴高悬，两旁辅以索链、铁栏勾连。]],["id"]=[[fb21_32]],["name"]=[[朝天宫]],["permission"]=2,["role1"]=[[fb21r32_1]],["role2"]=[[fb21r32_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb21_31]]},["fb21_33"]={["down"]=[[fb21_34]],["dsc"]=[[这里地势稍平，一道山涧缓缓流过，一座窄窄的木桥横在涧上，只容一人经过。]],["id"]=[[fb21_33]],["item1"]=[[bfitem1]],["name"]=[[会仙桥]],["permission"]=2,["role1"]=[[fb21r33_100]],["stepMusic"]=[[jiaobu]],["up"]=[[fb21_32]]},["fb21_34"]={["down"]=[[fb21_35]],["dsc"]=[[只见有石梯无数通往山巅，一座石坊上写着“头天门”三个大字，这是攀登武当绝顶天柱峰的起点。]],["fightBackground"]=[[山外]],["id"]=[[fb21_34]],["name"]=[[头天门]],["permission"]=2,["role1"]=[[fb21r34_1]],["role2"]=[[fb21r34_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb21_33]]},["fb21_35"]={["down"]=[[fb21_36]],["dsc"]=[[这里是“二天门”，金光灿灿的金顶就在眼前了。]],["fightBackground"]=[[山外]],["id"]=[[fb21_35]],["name"]=[[二天门]],["permission"]=2,["role1"]=[[fb21r35_1]],["role2"]=[[fb21r35_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb21_34]]},["fb21_36"]={["down"]=[[fb21_38]],["dsc"]=[[这里是登山石阶的尽头“三天门”，再往上走就是武当绝顶了。]],["fightBackground"]=[[山外]],["id"]=[[fb21_36]],["name"]=[[三天门]],["permission"]=2,["role1"]=[[fb21r36_1]],["role2"]=[[fb21r36_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb21_35]]},["fb21_37"]={["dsc"]=[[这里是武当绝顶的十二莲台，台与台之间以曲栏相连，雕刻精美，是远眺的最佳所在。站立此台四眺，往西可望到七百里外的华山，东望则汉水如练，襄、樊一带尽收眼底。]],["id"]=[[fb21_37]],["item1"]=[[fb21r37_102]],["item2"]=[[fb21item104]],["item3"]=[[fb21item107]],["name"]=[[十二莲台]],["permission"]=2,["right"]=[[fb21_38]],["role1"]=[[fb21r37_1]],["role2"]=[[fb21r37_2]],["role3"]=[[fb21r37_100]],["role4"]=[[fb21r37_101]],["stepMusic"]=[[jiaobu]]},["fb21_38"]={["down"]=[[fb21_39]],["dsc"]=[[你感到寒意阵阵袭来，原来你已到了武当山的主峰天柱峰的绝顶。前面的金殿由铜铸成，镀以黄金，每当旭日临空，整个殿宇金光闪闪，故名金顶。]],["id"]=[[fb21_38]],["left"]=[[fb21_37]],["name"]=[[金顶]],["permission"]=2,["role1"]=[[fb21r38_1]],["role2"]=[[fb21r38_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb21_36]]},["fb21_39"]={["down"]=[[fb21_40]],["dsc"]=[[这是守护金殿的紫金城墙，周长三里，城墙由花岗石依山势砌成，东西北城门均面临绝壁，南门为上下路口，气势壮观。]],["id"]=[[fb21_39]],["name"]=[[紫金城]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb21_38]]},["fb21_40"]={["dsc"]=[[金殿中间供着真武大帝铜像，披发跣足，体态丰满；左右有金童玉女侍立，虔诚恭敬，殿前供器皆为铜铸。殿宇和殿内铜像、供桌铆焊一体，构件精确，技巧高超。]],["id"]=[[fb21_40]],["item1"]=[[fb21item14]],["name"]=[[金殿]],["permission"]=2,["role1"]=[[fb21r40_1]],["role2"]=[[fb21r40_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb21_39]]},["fb21_41"]={["dsc"]=[[这里伸手不见五指。唯一的光亮来自石壁上那一道亮光。]],["id"]=[[fb21_41]],["item1"]=[[wabaorenwu10]],["name"]=[[阴暗洞穴]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb21_42]]},["fb21_42"]={["down"]=[[fb21_41]],["dsc"]=[[这里伸手不见五指。唯一的光亮来自石壁上那一道亮光。]],["id"]=[[fb21_42]],["item1"]=[[wabaorenwu5]],["left"]=[[fb21_43]],["name"]=[[阴暗洞穴]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb21_43"]={["dsc"]=[[这里伸手不见五指。唯一的光亮来自石壁上那一道亮光。]],["id"]=[[fb21_43]],["item1"]=[[wabaorenwu19]],["item2"]=[[wabaorenwu10]],["name"]=[[阴暗洞穴]],["permission"]=2,["right"]=[[fb21_42]],["stepMusic"]=[[jiaobu]]},["fb21_44"]={["down"]=[[fb21_45]],["dsc"]=[[你走在登山的路径上，路的左右各有一条大铁链，像两条长蛇向山上山下蜿蜒爬去。满眼是乔木夹道，如行于绿幕中。]],["id"]=[[fb21_44]],["name"]=[[山路]],["permission"]=2,["role1"]=[[fb21_32a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb21_02]]},["fb21_45"]={["dsc"]=[[你走在登山的路径上，路的左右各有一条大铁链，像两条长蛇向山上山下蜿蜒爬去。满眼是乔木夹道，如行于绿幕中。]],["id"]=[[fb21_45]],["item1"]=[[fubentiaozhuan1]],["name"]=[[山路]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb21_44]]}}0